package pose
import("testing";"encoding/json";"strings";"os";"path/filepath")
func b38rebuild(m ReleaseManifest) ReleaseManifest { return NewReleaseManifest(m.Version,m.PreviousVersion,m.PreparedAt,m.Fragments,ReleasePolicy{},ChangelogPolicy{},m.VersionEvidence) }
func TestB38IndependentProbes(t *testing.T) {
 t.Run("JSON shapes",func(t *testing.T){
 r:=newReleaseRepo(t,"v1.0.0"); good:=CanonicalJSON(r.manifest)
 for _,suffix:=range []string{"}","]"}{ _,issues:=ValidateReleaseManifestBytes(append(append([]byte{},good...),[]byte(suffix)...),r.version); t.Logf("trailing %q issues=%v",suffix,issues) }
 var doc map[string]any; _=json.Unmarshal(good,&doc)
 for _,field:=range []string{"breaking","specs","categories"}{ var d map[string]any;_=json.Unmarshal(good,&d); if field=="breaking" {delete(d,field)} else {d[field]=nil}; raw,_:=json.Marshal(d);_,issues:=ValidateReleaseManifestBytes(raw,r.version);t.Logf("missing/null %s issues=%v",field,issues) }
 for _,raw:=range [][]byte{[]byte(strings.Replace(string(good),`"schema_version": 1`,`"schema_version": 2, "schema_version": 1`,1)),[]byte(strings.Replace(string(good),`"version":`,`"VERSION":`,1))}{_,is:=ValidateReleaseManifestBytes(raw,r.version);t.Logf("duplicate/case folded issues=%v",is)}
 doc["breaking"]=nil; raw,_:=json.Marshal(doc);_,issues:=ValidateReleaseManifestBytes(raw,r.version);t.Logf("null breaking issues=%v",issues)
 })
 for _,name:=range []string{"fragment semantic","policy digest","version unequal","version removed","version nontext missing","version unknown kind","duplicate path","previous future","bad semver","required body empty"}{ t.Run(name,func(t *testing.T){
 r:=newReleaseRepo(t,"v1.0.0")
 switch name {
 case "fragment semantic":r.manifest.Fragments[0].Category="added";r.manifest.Fragments[0].Breaking=true;r.manifest.Fragments[0].Body="Forged body";r.manifest.Fragments[0].Refs="forged";r.manifest=b38rebuild(r.manifest)
 case "policy digest":relWrite(t,r.root,".pose/policy/release.json",string(CanonicalJSON(ReleasePolicy{SchemaVersion:1})));r.manifest.PolicyDigest=ReleaseDigest("forged");input:=struct{Version string `json:"version"`;Previous string `json:"previous"`;Fragments []ReleaseFragment `json:"fragments"`;Policy string `json:"policy"`;Evidence map[string]string `json:"evidence"`}{r.manifest.Version,r.manifest.PreviousVersion,r.manifest.Fragments,r.manifest.PolicyDigest,r.manifest.VersionEvidence};r.manifest.ReleaseInputDigest=ReleaseDigest(input)
 case "version unequal":r.manifest.VersionEvidence["value"]="v9.9.9";r.manifest=b38rebuild(r.manifest);relWrite(t,r.root,"VERSION","9.9.9\n")
 case "version removed":r.manifest.VersionEvidence=map[string]string{};r.manifest=b38rebuild(r.manifest)
 case "version unknown kind":r.manifest.VersionEvidence=map[string]string{"source":"VERSION","kind":"invented","value":r.version};r.manifest=b38rebuild(r.manifest)
 case "version nontext missing":r.manifest.VersionEvidence=map[string]string{"source":"missing.json","kind":"json","value":r.version};r.manifest=b38rebuild(r.manifest)
 case "duplicate path":f:=r.manifest.Fragments[0];f.Spec="beta";r.manifest.Fragments=append(r.manifest.Fragments,f);r.manifest=b38rebuild(r.manifest)
 case "bad semver":t.Logf("ValidateReleaseVersion(v1.0.0-..)=%v",ValidateReleaseVersion("v1.0.0-.."));return
 case "previous future":r.manifest.PreviousVersion="v9.9.9";r.manifest=b38rebuild(r.manifest)
 case "required body empty":r.manifest.Fragments[0].Body="";r.manifest=b38rebuild(r.manifest)
 }
 r.manifest.NotesDigest=ReleaseDigest(r.notes);relWrite(t,r.root,".pose/releases/v1.0.0/manifest.json",string(CanonicalJSON(r.manifest)));r.commit(t,name);relGit(t,r.root,"tag",r.version)
 snap,err:=ReadReleaseSnapshot(r.root,r.version);t.Logf("intact=%v issues=%v gaps=%v limits=%v err=%v",snap.Intact(),snap.Issues,snap.Gaps,snap.Limits,err)
 }) }
 t.Run("status ignores broken tagged notes",func(t *testing.T){r:=newReleaseRepo(t,"v1.0.0");relWrite(t,r.root,".pose/changelogs/v1.0.0.md","bad notes");r.commit(t,"bad notes");relGit(t,r.root,"tag",r.version);status,err:=(Store{Root:r.root}).GetReleaseStatus(r.version);if err!=nil {t.Fatal(err)};v:=status.Releases[0];t.Logf("state=%s gaps=%v snapshot_gaps=%v",v.State,v.Gaps,v.Snapshot.Gaps)})
 t.Run("status loses release directory",func(t *testing.T){r:=newReleaseRepo(t,"v1.0.0");relGit(t,r.root,"tag",r.version);_=os.RemoveAll(filepath.Join(r.root,".pose/releases"));s,err:=(Store{Root:r.root}).GetReleaseStatus("");t.Logf("releases=%v err=%v",s.Releases,err)})
 t.Run("base is not a directory",func(t *testing.T){r:=newReleaseRepo(t,"v1.0.0");_=os.RemoveAll(filepath.Join(r.root,".pose/releases"));relWrite(t,r.root,".pose/releases","not a directory");s,e:=(Store{Root:r.root}).GetReleaseStatus("");t.Logf("status=%+v error=%v",s,e)})
 t.Run("semantic prerelease ordering",func(t *testing.T){t.Logf("rc10 vs rc2=%d; final vs rc=%d",compareReleaseVersions("v1.0.0-rc.10","v1.0.0-rc.2"),compareReleaseVersions("v1.0.0","v1.0.0-rc.1"))})
 t.Run("read error archive dir",func(t *testing.T){r:=newReleaseRepo(t,"v1.0.0");r.manifest=NewReleaseManifest(r.version,"","2026-10-02T00:00:00Z",[]ReleaseFragment{},ReleasePolicy{},ChangelogPolicy{},r.manifest.VersionEvidence);relWrite(t,r.root,".pose/releases/v1.0.0/manifest.json",string(CanonicalJSON(r.manifest)));relWrite(t,r.root,".pose/changelogs/v1.0.0.md",RenderReleaseNotes(r.version,[]ReleaseFragment{},ChangelogPolicy{}));_=os.RemoveAll(filepath.Join(r.root,".pose/changelogs/v1.0.0"));relWrite(t,r.root,".pose/changelogs/v1.0.0","not a directory");r.commit(t,"bad archive");relGit(t,r.root,"tag",r.version);s,e:=ReadReleaseSnapshot(r.root,r.version);t.Logf("intact=%v gaps=%v err=%v",s.Intact(),s.Gaps,e)})
 _=strings.TrimSpace
}

