package cli
import("testing";"os";"os/exec";"path/filepath";"encoding/json";"strings";posemodel "github.com/harne8/pose-mcp/internal/pose")
func TestB38IndependentCLIProbes(t *testing.T){
 for _,name:=range []string{"same named branch","historical policy","path alias","prepared source changed","status broken notes","different worktree cut","record without snapshot","malformed pending"}{t.Run(name,func(t *testing.T){
 root:=cliReleaseRepo(t)
 git:=func(args ...string){t.Helper();cmd:=exec.Command("git",append([]string{"-C",root,"-c","user.name=t","-c","user.email=t@t","-c","commit.gpgsign=false"},args...)...);if out,e:=cmd.CombinedOutput();e!=nil{t.Fatalf("git: %v %s",e,out)}}
 mp:=filepath.Join(root,".pose/releases/v1.0.0/manifest.json");raw,_:=os.ReadFile(mp);var m posemodel.ReleaseManifest;_=json.Unmarshal(raw,&m)
 policy:=posemodel.ReleasePolicy{SchemaVersion:1};m=posemodel.NewReleaseManifest(m.Version,m.PreviousVersion,m.PreparedAt,m.Fragments,policy,posemodel.ChangelogPolicy{},m.VersionEvidence);writeCloseoutCLIFile(t,root,".pose/releases/v1.0.0/manifest.json",string(posemodel.CanonicalJSON(m)));writeCloseoutCLIFile(t,root,".pose/policy/release.json",string(posemodel.CanonicalJSON(policy)))
 switch name {
 case "malformed pending":writeCloseoutCLIFile(t,root,".pose/changelogs/unreleased/bad.md","not a fragment")
 case "record without snapshot":git("add","-A");git("commit","-qm","snapshot");git("rm","-qr",".pose");git("commit","-qm","no snapshot");git("tag","v1.0.0");git("checkout","HEAD^","--",".pose");out,e:=exec.Command("git","-C",root,"rev-parse","HEAD").Output();if e!=nil{t.Fatal(e)};ev:=posemodel.ReleaseEvidence{SchemaVersion:1,Provider:"github",Repository:"example/repo",Version:"v1.0.0",Tag:"v1.0.0",Commit:strings.TrimSpace(string(out))};writeCloseoutCLIFile(t,root,"evidence.json",string(posemodel.CanonicalJSON(ev)));code,msg:=runPose(t,root,"release","record","--version","v1.0.0","--event","tagged","--evidence","evidence.json");t.Logf("record code=%d %s",code,msg)
 case "same named branch":git("branch","v1.0.0")
 case "historical policy":git("add","-A");git("commit","-qm","policy");git("tag","v1.0.0");policy.AllowEmpty=true;writeCloseoutCLIFile(t,root,".pose/policy/release.json",string(posemodel.CanonicalJSON(policy)))
 case "path alias":m.Fragments[0].Path="other.md";m=posemodel.NewReleaseManifest(m.Version,m.PreviousVersion,m.PreparedAt,m.Fragments,policy,posemodel.ChangelogPolicy{},m.VersionEvidence);writeCloseoutCLIFile(t,root,".pose/releases/v1.0.0/manifest.json",string(posemodel.CanonicalJSON(m)))
 case "prepared source changed":writeCloseoutCLIFile(t,root,"VERSION","9.9.9\n")
 case "different worktree cut":git("add","-A");git("commit","-qm","cut A");git("tag","v1.0.0");old:=filepath.Join(root,".pose/changelogs/v1.0.0/alpha.md");raw,_:=os.ReadFile(old);body:=strings.ReplaceAll(string(raw),"Fixes alpha.","Different cut B.");writeCloseoutCLIFile(t,root,".pose/changelogs/v1.0.0/alpha.md",body);m.Fragments[0].Body="Different cut B.";m.Fragments[0].Digest=posemodel.ReleaseDigest(body);m=posemodel.NewReleaseManifest(m.Version,m.PreviousVersion,m.PreparedAt,m.Fragments,policy,posemodel.ChangelogPolicy{},m.VersionEvidence);writeCloseoutCLIFile(t,root,".pose/releases/v1.0.0/manifest.json",string(posemodel.CanonicalJSON(m)));writeCloseoutCLIFile(t,root,".pose/changelogs/v1.0.0.md",posemodel.RenderReleaseNotes(m.Version,m.Fragments,posemodel.ChangelogPolicy{}))
 case "status broken notes":writeCloseoutCLIFile(t,root,".pose/changelogs/v1.0.0.md","broken");git("add","-A");git("commit","-qm","broken");git("tag","v1.0.0")
 }
 code,out:=runPose(t,root,"release","check","--version","v1.0.0","--json","--strict");t.Logf("check code=%d %s",code,out)
 if name=="status broken notes"{code,out=runPose(t,root,"release","status");t.Logf("status code=%d %s",code,out)}
 _=strings.TrimSpace
 })}
}
